def icon(symbol): return f'<div class="icon" aria-hidden="true"><span>{symbol}</span></div>'
def card(title, text, symbol='✳', extra=''):
    return f'<article class="card reveal">{icon(symbol)}<h3>{title}</h3><p>{text}</p>{extra}</article>'
def shell(title, desc, slug, body):
    nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if href==slug else '')+f'>{label}</a>' for label,href in NAV)
    nav+= '<a href="team.html">Team</a><a href="testimonials.html">Testimonials</a><a href="blog.html">Resources</a><a class="btn nav-cta" href="contact.html">Free consultation</a>'
    footer='''<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="index.html"><span class="brand-mark">D</span>Digital Growth Hub</a><p style="margin-top:18px">Strategy, creative, and digital marketing for businesses ready to grow with intention.</p><form class="newsletter"><label class="sr-only" for="newsletter-email">Email address</label><input id="newsletter-email" name="email" type="email" placeholder="Your email" required><button class="btn" type="submit">Subscribe</button><span class="newsletter-status status" aria-live="polite"></span></form><small>Newsletter signup is in preview mode until an endpoint is configured.</small></div><div><h3>Explore</h3><div class="footer-links"><a href="about.html">About</a><a href="team.html">Our team</a><a href="work.html">Work</a><a href="testimonials.html">Testimonials</a></div></div><div><h3>Services</h3><div class="footer-links"><a href="services.html">All services</a><a href="services.html#seo">SEO</a><a href="services.html#web-design">Website design</a><a href="services.html#social">Social media</a></div></div><div><h3>Get in touch</h3><div class="footer-links"><a href="contact.html">Contact</a><a data-contact-email href="contact.html">[Business email to be configured]</a><a data-booking hidden target="_blank" rel="noopener">Book a consultation</a><a href="https://www.linkedin.com/" target="_blank" rel="noopener">LinkedIn ↗</a><a href="https://www.instagram.com/" target="_blank" rel="noopener">Instagram ↗</a></div></div></div><div class="footer-bottom"><small>© <span data-year></span> Digital Growth Hub. Website content and sample projects are for preview.</small><div><a href="privacy.html">Privacy draft</a><a href="terms.html">Terms draft</a></div></div></div></footer>'''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Digital Growth Hub</title><meta name="description" content="{desc}"><meta property="og:title" content="{title} | Digital Growth Hub"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta name="theme-color" content="#0A0A0F"><link rel="stylesheet" href="assets/css/styles.css"><script defer src="assets/js/config.js"></script><script defer src="assets/js/main.js"></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.html"><span class="brand-mark">D</span>Digital Growth Hub</a><button class="menu-toggle" aria-label="Open navigation menu" aria-expanded="false" aria-controls="site-navigation"><span></span><span></span></button><nav class="nav-links" id="site-navigation" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main>{footer}<script>document.querySelectorAll('[data-year]').forEach(e=>e.textContent=new Date().getFullYear())</script></body></html>'''

